11. //==================================================================================================
12. // Helper Lemmas
13. //==================================================================================================
14. 
15. /// Pushing an element not already present onto a no-duplicate sequence preserves no_duplicates.
16. proof fn lemma_push_preserves_no_dup<K>(s: Seq<K>, elem: K)
17.     requires
18.         s.no_duplicates(),
19.         !s.contains(elem),
20.     ensures
21.         s.push(elem).no_duplicates(),
22. {
23.     broadcast use vstd::seq_lib::group_seq_properties;
24. 
25.     let pushed = s.push(elem);
26.     assert forall |i: int, j: int|
27.         0 <= i < pushed.len() && 0 <= j < pushed.len() && i != j
28.     implies
29.         pushed[i] != pushed[j]
30.     by {
31.         // Both indices within original: covered by s.no_duplicates().
32.         // One index at s.len() (the pushed element): s[other] != elem
33.         // because !s.contains(elem) and s.contains(s[other]).
34.     }
35. }
36. 
37. /// Filtering preserves no_duplicates.
38. proof fn lemma_filter_preserves_no_dup<K>(s: Seq<K>, pred: spec_fn(K) -> bool)
39.     requires
40.         s.no_duplicates(),
41.     ensures
42.         s.filter(pred).no_duplicates(),
43.     decreases s.len(),
44. {
45.     broadcast use vstd::seq_lib::group_seq_properties;
46.     reveal(Seq::filter);
47. 
48.     if s.len() > 0 {
49.         let rest = s.drop_last();
50.         let last = s.last();
51. 
52.         lemma_filter_preserves_no_dup(rest, pred);
53. 
54.         if pred(last) {
55.             assert(!rest.filter(pred).contains(last)) by {
56.                 if rest.filter(pred).contains(last) {
57.                     rest.lemma_filter_contains_rev(pred, last);
58.                 }
59.             };
60.             lemma_push_preserves_no_dup(rest.filter(pred), last);
61.         }
62.     }
63. }
64. 
65. /// filter(|k| k != key).to_set() equals to_set().remove(key).
66. proof fn lemma_filter_neq_to_set<K>(s: Seq<K>, key: K)
67.     ensures
68.         s.filter(|k: K| k != key).to_set() =~= s.to_set().remove(key),
69. {
70.     broadcast use vstd::seq_lib::group_seq_properties, vstd::set::group_set_axioms;
71. 
72.     let pred = |k: K| k != key;
73.     let filtered = s.filter(pred);
74. 
75.     assert forall |x: K|
76.         filtered.to_set().contains(x) implies s.to_set().remove(key).contains(x)
77.     by {
78.         s.lemma_filter_contains_rev(pred, x);
79.         let idx = choose |idx: int| 0 <= idx < filtered.len() && filtered[idx] == x;
80.         s.lemma_filter_pred(pred, idx);
81.     };
82. 
83.     assert forall |x: K|
84.         s.to_set().remove(key).contains(x) implies filtered.to_set().contains(x)
85.     by {
86.         let idx = choose |idx: int| 0 <= idx < s.len() && s[idx] == x;
87.         s.lemma_filter_contains(pred, idx);
88.     };
89. }
90. 
91. /// For a no-duplicate sequence containing key, filter(!=key) reduces length by exactly 1.
92. proof fn lemma_filter_neq_len<K>(s: Seq<K>, key: K)
93.     requires
94.         s.no_duplicates(),
95.         s.contains(key),
96.     ensures
97.         s.filter(|k: K| k != key).len() == s.len() - 1,
98. {
99.     broadcast use vstd::set::group_set_axioms, vstd::seq_lib::seq_to_set_is_finite;
100. 
101.     let pred = |k: K| k != key;
102.     let filtered = s.filter(pred);
103. 
104.     lemma_filter_preserves_no_dup(s, pred);
105.     lemma_filter_neq_to_set(s, key);
106. 
107.     s.unique_seq_to_set();
108.     filtered.unique_seq_to_set();
109. }
110. 
111. /// Subrange of a no-duplicate sequence is no-duplicate.
112. proof fn lemma_subrange_no_dup<K>(s: Seq<K>, start: int, stop: int)
113.     requires
114.         s.no_duplicates(),
115.         0 <= start <= stop <= s.len(),
116.     ensures
117.         s.subrange(start, stop).no_duplicates(),
118. {
119.     let sub = s.subrange(start, stop);
120.     assert forall |i: int, j: int|
121.         0 <= i < sub.len() && 0 <= j < sub.len() && i != j
122.     implies
123.         sub[i] != sub[j]
124.     by {
125.         // sub[i] == s[start + i], sub[j] == s[start + j],
126.         // and start + i != start + j since i != j.
127.     }
128. }
129. 
130. /// For a no-dup sequence: subrange(1, len).to_set() == to_set().remove(first).
131. proof fn lemma_drop_first_to_set<K>(s: Seq<K>)
132.     requires
133.         s.no_duplicates(),
134.         s.len() > 0,
135.     ensures
136.         s.subrange(1, s.len() as int).to_set() =~= s.to_set().remove(s[0]),
137. {
138.     broadcast use vstd::seq_lib::group_seq_properties, vstd::set::group_set_axioms;
139. 
140.     let sub = s.subrange(1, s.len() as int);
141. 
142.     assert forall |x: K|
143.         sub.to_set().contains(x) implies s.to_set().remove(s[0]).contains(x)
144.     by {
145.         vstd::seq_lib::lemma_seq_subrange_elements(s, 1int, s.len() as int, x);
146.     };
147. 
148.     assert forall |x: K|
149.         s.to_set().remove(s[0]).contains(x) implies sub.to_set().contains(x)
150.     by {
151.         let idx = choose |idx: int| 0 <= idx < s.len() && s[idx] == x;
152.         vstd::seq_lib::lemma_seq_subrange_elements(s, 1int, s.len() as int, x);
153.     };
154. }
155. 
156. //==================================================================================================
157. // Invariant Preservation Lemmas
158. //==================================================================================================
159. 
160. /// `spec_new` produces a well-formed cache view.
161. proof fn lemma_spec_new_inv<K, V>(capacity: nat)
162.     ensures
163.         CacheView::<K, V>::spec_new(capacity).inv(),
164. {
165.     broadcast use vstd::set::group_set_axioms, vstd::map::group_map_axioms,
166.         vstd::seq_lib::seq_to_set_is_finite;
167. 
168.     let cv = CacheView::<K, V>::spec_new(capacity);
169.     assert(cv.contents.dom() =~= Set::<K>::empty());
170.     assert(cv.lru_order.to_set() =~= Set::<K>::empty());
171. }
172. 
173. /// `spec_get` preserves the invariant.
174. proof fn lemma_spec_get_inv<K, V>(cache: CacheView<K, V>, key: K)
175.     requires
176.         cache.inv(),
177.     ensures
178.         cache.spec_get(key).0.inv(),
179. {
180.     broadcast use vstd::set::group_set_axioms, vstd::map::group_map_axioms,
181.         vstd::seq_lib::seq_to_set_is_finite;
182. 
183.     if cache.contents.dom().contains(key) {
184.         let pred = |k: K| k != key;
185.         let filtered = cache.lru_order.filter(pred);
186. 
187.         // 1. no_duplicates for move_to_mru
188.         lemma_filter_preserves_no_dup(cache.lru_order, pred);
189.         assert(!filtered.contains(key)) by {
190.             if filtered.contains(key) {
191.                 let idx = choose |idx: int| 0 <= idx < filtered.len() && filtered[idx] == key;
192.                 cache.lru_order.lemma_filter_pred(pred, idx);
193.             }
194.         };
195.         lemma_push_preserves_no_dup(filtered, key);
196. 
197.         // 2. to_set: mru.to_set() == contents.dom()
198.         lemma_filter_neq_to_set(cache.lru_order, key);
199.         filtered.lemma_push_to_set_commute(key);
200. 
201.         // 3. len
202.         lemma_filter_neq_len(cache.lru_order, key);
203.     }
204. }
205. 
206. /// `spec_put` preserves the invariant.
207. proof fn lemma_spec_put_inv<K, V>(cache: CacheView<K, V>, key: K, value: V)
208.     requires
209.         cache.inv(),
210.     ensures
211.         cache.spec_put(key, value).inv(),
212. {
213.     broadcast use vstd::set::group_set_axioms, vstd::map::group_map_axioms,
214.         vstd::seq_lib::seq_to_set_is_finite;
215. 
216.     if cache.capacity == 0 {
217.         // Zero-capacity: no-op.
218.     } else if cache.contents.dom().contains(key) {
219.         // Overwrite existing key.
220.         let pred = |k: K| k != key;
221.         let filtered = cache.lru_order.filter(pred);
222. 
223.         // no_duplicates
224.         lemma_filter_preserves_no_dup(cache.lru_order, pred);
225.         assert(!filtered.contains(key)) by {
226.             if filtered.contains(key) {
227.                 let idx = choose |idx: int| 0 <= idx < filtered.len() && filtered[idx] == key;
228.                 cache.lru_order.lemma_filter_pred(pred, idx);
229.             }
230.         };
231.         lemma_push_preserves_no_dup(filtered, key);
232. 
233.         // to_set
234.         lemma_filter_neq_to_set(cache.lru_order, key);
235.         filtered.lemma_push_to_set_commute(key);
236.         assert(cache.contents.insert(key, value).dom() =~= cache.contents.dom());
237. 
238.         // len
239.         lemma_filter_neq_len(cache.lru_order, key);
240. 
241.     } else if cache.contents.dom().len() >= cache.capacity {
242.         // At capacity, new key: evict LRU victim.
243.         let sub = cache.lru_order.subrange(1, cache.lru_order.len() as int);
244.         let new_lru = sub.push(key);
245. 
246.         // sub.no_duplicates
247.         lemma_subrange_no_dup(cache.lru_order, 1, cache.lru_order.len() as int);
248. 
249.         // key not in sub
250.         assert(!sub.contains(key)) by {
251.             if sub.contains(key) {
252.                 vstd::seq_lib::lemma_seq_subrange_elements(
253.                     cache.lru_order, 1int, cache.lru_order.len() as int, key,
254.                 );
255.             }
256.         };
257. 
258.         // new_lru.no_duplicates
259.         lemma_push_preserves_no_dup(sub, key);
260. 
261.         // to_set: new_lru.to_set() == result.contents.dom()
262.         lemma_drop_first_to_set(cache.lru_order);
263.         sub.lemma_push_to_set_commute(key);
264. 
265.         // len
266.         new_lru.unique_seq_to_set();
267. 
268.     } else {
269.         // Below capacity, new key: insert directly.
270. 
271.         // no_duplicates
272.         lemma_push_preserves_no_dup(cache.lru_order, key);
273. 
274.         // to_set
275.         cache.lru_order.lemma_push_to_set_commute(key);
276.     }
277. }
278. 
279. /// `spec_remove` preserves the invariant.
280. proof fn lemma_spec_remove_inv<K, V>(cache: CacheView<K, V>, key: K)
281.     requires
282.         cache.inv(),
283.     ensures
284.         cache.spec_remove(key).inv(),
285. {
286.     broadcast use vstd::set::group_set_axioms, vstd::map::group_map_axioms,
287.         vstd::seq_lib::seq_to_set_is_finite;
288. 
289.     if cache.contents.dom().contains(key) {
290.         let pred = |k: K| k != key;
291.         let filtered = cache.lru_order.filter(pred);
292. 
293.         // no_duplicates
294.         lemma_filter_preserves_no_dup(cache.lru_order, pred);
295. 
296.         // to_set
297.         lemma_filter_neq_to_set(cache.lru_order, key);
298. 
299.         // len
300.         lemma_filter_neq_len(cache.lru_order, key);
301.         filtered.unique_seq_to_set();
302.     }
303. }
304. 
305. /// `spec_clear` preserves the invariant.
306. proof fn lemma_spec_clear_inv<K, V>(cache: CacheView<K, V>)
307.     requires
308.         cache.inv(),
309.     ensures
310.         cache.spec_clear().inv(),
311. {
312.     broadcast use vstd::set::group_set_axioms, vstd::map::group_map_axioms,
313.         vstd::seq_lib::seq_to_set_is_finite;
314. 
315.     let cv = cache.spec_clear();
316.     assert(cv.contents.dom() =~= Set::<K>::empty());
317.     assert(cv.lru_order.to_set() =~= Set::<K>::empty());
318. }
319. 
320. } // verus!
